package hu.synostream.android;
import android.app.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.os.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import androidx.core.content.FileProvider;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
@RunWith(AndroidJUnit4.class) public class Android0519Test {
 final Android050FlowTest f=new Android050FlowTest();AppUpdates updates;File fixture;
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");updates=AppUpdates.get(f.context);updates.automatic(false);updates.checked=true;fixture=new File(f.context.getExternalFilesDir(null),"update-fixture.apk");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{updates.source=AppRelease::fetch;updates.permissionReturn=false;updates.busy=false;updates.download=false;updates.available=null;updates.ready=false;updates.installRequested=true;updates.closeProgress();Dialog d=updates.offer.get();if(d!=null)d.dismiss();f.app.automaticForeground(false);f.app.cancelScan();});f.cleanup();}
 AppRelease release()throws Exception{return release("993702ff90412c5aefcb43797d67adccb7bcdf62969f215fb92e9a5c52bca857");}
 AppRelease release(String certificate)throws Exception{return new AppRelease(new JSONObject().put("format",1).put("platform","android").put("application_id",f.pkg).put("version","0.5.19").put("version_code",24).put("min_sdk",26).put("filename","SynoStream_Android_0.5.19.apk").put("url","https://github.com/x10ilaci/SynoStream/releases/download/android-v0.5.19/SynoStream_Android_0.5.19.apk").put("size",fixture.length()).put("sha256",AppRelease.digest(fixture)).put("signing_certificate_sha256",certificate).put("notes","Updater fixture"));}
 void waitFor(java.util.function.BooleanSupplier c)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(!c.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue(c.getAsBoolean());}
 void setup(FakeNas nas)throws Exception{f.setup(nas,List.of(new Library.Card("/Movies/Demo.Movie.2020.mkv","Fixture",true)));}
 @Test public void archiveIdentityAndHashAreCheckedAgainstInstalledCertificate()throws Exception{assertTrue(fixture.isFile());AppRelease r=release();ApkIdentity.verify(f.context,fixture,r);assertThrows(Exception.class,()->ApkIdentity.verify(f.context,fixture,release("a".repeat(64))));File corrupt=new File(f.context.getCacheDir(),"corrupt.apk");try(FileOutputStream out=new FileOutputStream(corrupt)){out.write(new byte[]{1,2,3});}try{assertThrows(Exception.class,()->ApkIdentity.verify(f.context,corrupt,r));}finally{corrupt.delete();}}
 @Test public void providerOnlyExposesUpdateCache()throws Exception{File dir=new File(f.context.getCacheDir(),"updates");dir.mkdirs();File file=new File(dir,"probe.apk");try(FileOutputStream out=new FileOutputStream(file)){out.write(1);}try{Uri uri=FileProvider.getUriForFile(f.context,f.pkg+".updates",file);assertEquals("content",uri.getScheme());try(InputStream in=f.context.getContentResolver().openInputStream(uri)){assertEquals(1,in.read());}assertThrows(IllegalArgumentException.class,()->FileProvider.getUriForFile(f.context,f.pkg+".updates",new File(f.context.getFilesDir(),"credentials")));}finally{file.delete();}}
 @Test public void settingsExposeManualAndPersistentAutomaticCheck()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{f.app.page="settings";a.invalidatePage();});assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/update_check")),5000));f.text("Frissítés ellenőrzése indításkor");assertTrue(updates.automatic());updates.automatic(false);}}
 @Test public void approvedApkLaunchesAndroidInstallerWithReadGrant()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);assertTrue(f.context.getPackageManager().canRequestPackageInstalls());AppRelease r=release();updates.apk().getParentFile().mkdirs();java.nio.file.Files.copy(fixture.toPath(),updates.apk().toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);AtomicReference<Intent> intent=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent i){if(Intent.ACTION_VIEW.equals(i.getAction())&&"application/vnd.android.package-archive".equals(i.getType())){intent.set(i);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};f.instrumentation.addMonitor(monitor);try{f.instrumentation.runOnMainSync(()->{updates.available=r;updates.ready=true;updates.installRequested=false;updates.install();});waitFor(()->intent.get()!=null);assertEquals("content",intent.get().getData().getScheme());assertTrue((intent.get().getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);try(InputStream in=f.context.getContentResolver().openInputStream(intent.get().getData())){assertEquals(fixture.length(),in.readAllBytes().length);}}finally{f.instrumentation.removeMonitor(monitor);}}}

 @Test public void startupChecksOnceAndManualWorksWhenAutomaticIsOff()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{updates.source=()->{calls.incrementAndGet();return release();};updates.checked=false;updates.automatic(true);updates.resumed(a);});waitFor(()->calls.get()==1&&!updates.busy);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/update_install")),5000));f.text("Később");f.instrumentation.runOnMainSync(()->updates.resumed(a));Thread.sleep(200);assertEquals(1,calls.get());f.instrumentation.runOnMainSync(()->{updates.automatic(false);updates.checked=false;updates.resumed(a);});Thread.sleep(200);assertEquals(1,calls.get());f.instrumentation.runOnMainSync(()->updates.check(true));waitFor(()->calls.get()==2&&!updates.busy);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/update_install")),5000));f.text("Később");}}

 @Test public void missingInstallPermissionOffersAndroidSourceSettings()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);assertFalse(f.context.getPackageManager().canRequestPackageInstalls());AppRelease r=release();updates.apk().getParentFile().mkdirs();java.nio.file.Files.copy(fixture.toPath(),updates.apk().toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);AtomicReference<Intent> captured=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent i){if(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES.equals(i.getAction())){captured.set(i);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};f.instrumentation.addMonitor(monitor);try{f.instrumentation.runOnMainSync(()->{updates.available=r;updates.ready=true;updates.installRequested=false;updates.install();});androidx.test.uiautomator.BySelector open=By.text(java.util.regex.Pattern.compile("(?iu)beállítás megnyitása"));boolean visible=f.device.wait(Until.hasObject(open),10000);f.device.takeScreenshot(new File(f.context.getExternalFilesDir(null),"permission-proof.png"));assertTrue("Install permission prompt is visible",visible);f.device.findObject(open).click();waitFor(()->captured.get()!=null);assertEquals("package:"+f.pkg,captured.get().getDataString());}finally{f.instrumentation.removeMonitor(monitor);}}}

 @Test public void publicGitHubFeedAndApkDownload()throws Exception{AppRelease r=AppRelease.fetch();File file=new File(f.context.getCacheDir(),"updates/network-proof.apk");try{r.download(file,(n,total)->{});r.verify(file);assertTrue(file.length()>100000);}finally{file.delete();}}
 @Test public void realInstallerForExternalUpgradeProof()throws Exception{if(!"yes".equals(InstrumentationRegistry.getArguments().getString("real_install")))return;try(FakeNas nas=new FakeNas()){setup(nas);AppRelease r=release();updates.apk().getParentFile().mkdirs();java.nio.file.Files.copy(fixture.toPath(),updates.apk().toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);f.context.getSharedPreferences("upgrade_proof",0).edit().putString("retained","fixture-preserved").commit();f.instrumentation.runOnMainSync(()->{updates.available=r;updates.ready=true;updates.installRequested=false;updates.install();});Thread.sleep(5000);}}
}
